  let root = Map.new

  root.set('model', Json.String(agent_id))
  root.set('input', input)
  root.set('max_output_tokens', Json.Int(max_tokens))

  Result.Ok(Json.Object(root).to_string)
}

type AzureOpenAIClient {
  let @endpoint: String
  let @api_key: String
  let @agent_id: String

  fn static new(endpoint: String, api_key: String, agent_id: String) -> Self {
    Self(
      endpoint: strip_trailing_slashes(endpoint),
      api_key: api_key,
      agent_id: agent_id,
    )
  }

  fn responses_create(input_json: String, max_tokens: Int) -> Result[String, String] {
    let body = try build_responses_body(input_json, @agent_id.clone, max_tokens)
    let url = '${@endpoint}/openai/v1/responses'
    let uri = try parse_uri(url, label: 'responses endpoint')
    let client = Client.new

    let response = match client
      .post(uri)
      .header(Header.new('accept'), 'application/json')
      .header(Header.new('content-type'), 'application/json')
      .header(Header.new('api-key'), @api_key.clone)
      .body(body) {
      case Ok(value) -> value
      case Error(error) -> {
        return Result.Error('Request failed: ${error}')
      }
    }

    let status = response.status.to_int
    let response_body = try read_response_body(response, 'responses response body')

    if status < 200 or status >= 300 {
      return Result.Error(
        'HTTP ${status}: ${error_message_from_body(response_body)}',
      )
    }

    extract_output_text(response_body)
  }
}

type async Main {
  fn async main {
    let stdout = Stdout.new
    let stderr = Stderr.new

    let input_json = match read_string_limited(Stdin.new, 'stdin input', MAX_INPUT_BYTES) {
      case Ok(value) -> value
      case Error(error) -> {
        let _ = stderr.print('Error: ${error}')
        let _ = stderr.flush
        return
      }
    }

    let api_key = match required_env('AZURE_API_KEY') {
      case Ok(value) -> value
      case Error(error) -> {
        let _ = stderr.print('Error: ${error}')
        let _ = stderr.flush
        return
      }
    }

    let endpoint = optional_env('AZURE_EXISTING_AIPROJECT_ENDPOINT', DEFAULT_ENDPOINT)
    let agent_id = optional_env('AZURE_EXISTING_AGENT_ID', DEFAULT_AGENT_ID)
    let client = AzureOpenAIClient.new(endpoint, api_key, agent_id)

    match client.responses_create(input_json, MAX_TOKENS) {
      case Ok(output_text) -> {
        let _ = stdout.write(output_text)
        let _ = stdout.flush
      }
      case Error(error) -> {
        let _ = stderr.print('Error: ${error}')
        let _ = stderr.flush
      }
    }
  }
}



